export const activities=[['喂食','日常','01-喂食'],['换水','日常','02-换水'],['排便','日常','03-排便'],['散步','日常','04-散步'],['遛狗','日常','04-散步'],['体重','健康','05-体重'],['驱虫','健康','06-驱虫'],['疫苗','健康','07-疫苗'],['用药','健康','08-用药'],['洗澡','日常','09-洗澡'],['梳毛','日常','10-梳毛'],['刷牙','日常','11-刷牙'],['剪指甲','日常','12-剪指甲'],['日记','回忆','13-日记'],['照片','回忆','14-照片'],['换猫砂','日常','15-换猫砂']];
export const fresh=()=>({version:1,pets:[],records:[],tasks:[],current:'',processed:[]});
export function nextTime(time,days){const date=new Date(time);date.setDate(date.getDate()+Number(days));return date.toISOString();}
export function nextTaskTime(task,completedAt){if(task.repeat==='once')return null;if(!Number.isInteger(Number(task.days))||Number(task.days)<1)throw Error('安排间隔无效');if(task.repeat==='fixed'){let at=nextTime(task.at,task.days);while(new Date(at)<=new Date(completedAt))at=nextTime(at,task.days);return at;}return nextTime(completedAt,task.days);}
export function finishTask(state,id,record,operation){if(state.processed.includes(operation))return state;const task=state.tasks.find(t=>t.id===id);if(!task||task.status!=='pending')throw Error('该安排已经处理');const automatic=nextTaskTime(task,record.at),at=record.nextAt||automatic;if(at&&(!Number.isFinite(new Date(at).getTime())||new Date(at)<=new Date(record.at)))throw Error('下次安排必须晚于实际完成时间');const result=structuredClone(state),target=result.tasks.find(t=>t.id===id);target.status='done';target.recordId=record.id;target.completedAt=record.at;result.records.push({...record,taskId:id});if(automatic){result.tasks.push({...task,id:record.id+'-next',at:new Date(at).toISOString(),status:'pending',recordId:null,completedAt:null});}result.processed.push(operation);return result;}

export function deletePet(state,id){const pet=state.pets.find(p=>p.id===id);if(!pet)throw Error('档案不存在');const pets=state.pets.filter(p=>p.id!==id);return {...state,pets,records:state.records.filter(r=>r.petId!==id),tasks:state.tasks.filter(t=>t.petId!==id),current:state.current===id?(pets[0]?.id||''):state.current,deletedPets:[...(state.deletedPets||[]),{pet,records:state.records.filter(r=>r.petId===id),tasks:state.tasks.filter(t=>t.petId===id)}]};}
export function restorePet(state){const removed=state.deletedPets?.at(-1);if(!removed)return state;if(state.pets.some(p=>p.id===removed.pet.id))throw Error('该档案已经存在');return {...state,pets:[...state.pets,removed.pet],records:[...state.records,...removed.records],tasks:[...state.tasks,...removed.tasks],current:state.current||removed.pet.id,deletedPets:state.deletedPets.slice(0,-1)};}

